import React, { useEffect, useState, useRef } from 'react'; // 1
import { io } from 'socket.io-client';                      // 2
import API from '../utils/api';                             // 3

export default function Chat({ user, onLogout }) {         // 4
  const [messages, setMessages] = useState([]);             // 5
  const [text, setText] = useState('');                     // 6
  const socketRef = useRef(null);                           // 7

  useEffect(() => {                                         // 8
    // create socket with token for auth
    const token = localStorage.getItem('token');           // 9
    const socket = io('http://localhost:5000', { auth: { token } }); // 10
    socketRef.current = socket;                            // 11

    // receive history
    socket.on('chat history', (msgs) => setMessages(msgs)); // 12

    // receive single message
    socket.on('chat message', (msg) => setMessages(prev => [...prev, msg])); // 13

    return () => {                                         // 14
      socket.disconnect();                                // 15
    };
  }, []);                                                  // 16

  // send message
  const send = () => {                                     // 17
    if (!text.trim()) return;                              // 18
    socketRef.current.emit('chat message', text);         // 19
    setText('');                                           // 20
  };

  // fetch messages via API (optional sync)
  const refresh = async () => {                            // 21
    const res = await API.get('/messages');                // 22
    setMessages(res.data);                                 // 23
  };

  return (                                                // 24
    <div style={{ maxWidth: 700 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <h3>Group Chat</h3>
        <div>
          <span style={{ marginRight: 8 }}>{user.username}</span>
          <button onClick={onLogout}>Logout</button>
        </div>
      </div>

      <div style={{ border: '1px solid #ddd', height: 400, overflowY: 'auto', padding: 8, marginBottom: 8 }}>
        {messages.map((m) => (
          <div key={m._id} style={{ padding: 6, borderBottom: '1px solid #eee' }}>
            <strong>{m.sender}</strong>: {m.text}
            <div style={{ fontSize: 11, color: '#666' }}>{new Date(m.timestamp).toLocaleString()}</div>
          </div>
        ))}
      </div>

      <div style={{ display: 'flex' }}>
        <input value={text} onChange={e => setText(e.target.value)} onKeyDown={e => e.key === 'Enter' && send()} placeholder="Type a message..." style={{ flex: 1, padding: 8 }} />
        <button onClick={send} style={{ padding: 8 }}>Send</button>
      </div>
      <div style={{ marginTop: 8 }}>
        <button onClick={refresh} style={{ padding: 6 }}>Refresh (API)</button>
      </div>
    </div>
  );
}
